export async function POST(request:Request){const context=requestContext(request,"/api/account/refund");try{const identity=await getRequestIdentity();if(!identity||identity.isAnonymous)return apiError(context,"account_required","Sign in to request a purchase refund.",401);const parsed=await parseJson(request,schema,4_096);const quote=asQuote(await getRefundQuote(identity.userId,parsed.purchaseId));
